/** Fluid · alternate value for a UI mode · text → CSS px. */
export const fwspMode = /* @__PURE__ */ modeFn(B, DpQualifier.WIDTH, KIND_SP, false);
/** Fluid · alternate value for a UI mode · text → device px. */
export const fwspModePx = /* @__PURE__ */ modeFn(B, DpQualifier.WIDTH, KIND_SP, true);
