export const fwspQualifier = /* @__PURE__ */ qualifierFn(B, DpQualifier.WIDTH, KIND_SP, false);
/** Fluid · alternate value above a dp threshold · text → device px. */
export const fwspQualifierPx = /* @__PURE__ */ qualifierFn(B, DpQualifier.WIDTH, KIND_SP, true);
