// ── Builder (Android `DimenFluid` / `FluidSp`). ───────────────────────────
/** Custom-dimension builder for the fluid strategy. */
export class DimenFluid extends DimenBuilder {
  get fsdp(): number { return this.sdp; }
  get fsdpPx(): number { return this.sdpPx; }
  get fssp(): number { return this.ssp; }
  get fsspPx(): number { return this.sspPx; }
  get fsem(): number { return this.sem; }
  get fsemPx(): number { return this.semPx; }
  get fhdp(): number { return this.hdp; }
  get fhdpPx(): number { return this.hdpPx; }
  get fhsp(): number { return this.hsp; }
  get fhspPx(): number { return this.hspPx; }
  get fhem(): number { return this.hem; }
  get fhemPx(): number { return this.hemPx; }
  get fwdp(): number { return this.wdp; }
  get fwdpPx(): number { return this.wdpPx; }
  get fwsp(): number { return this.wsp; }
  get fwspPx(): number { return this.wspPx; }
  get fwem(): number { return this.wem; }
  get fwemPx(): number { return this.wemPx; }
}
/** Starts a builder: `fluidDp(16).screen(UiModeType.TELEVISION, 40).fsdp`. */
export const fluidDp = (value: number): DimenFluid => new DimenFluid(B, value);
/** Text builder (same class; read `.fssp` / `.fsem`). */
export const fluidSp = (value: number): DimenFluid => new DimenFluid(B, value);
